const rawTitle = (item.json['Title'] || '').trim();
if (!rawTitle) return { json: { ...item.json, _raw_title_cleaned: '', _title_error: 'Title empty' } };
let cleaned = rawTitle
  .replace(/^[A-Z0-9]{2,}-[A-Z0-9-]+\s+/i, '')
  .replace(/^(Black|White|Grey|Gray|Red|Blue|Green|Yellow|Pink|Purple|Orange|Brown|Silver|Gold|Beige|Khaki|Navy|Cream|Clear|Dark|Light)\s+/i, '')
  .replace(/\s{2,}/g, ' ')
  .trim();
const category = item.json['Category'] || '';
const subcat = item.json['Subcategory'] || '';
const subsubcat = item.json['Sub_subcategory'] || '';
const description = (item.json['Description'] || '').replace(/<[^>]+>/g, ' ').replace(/\s{2,}/g, ' ').trim().substring(0, 500);
return {
  json: {
    ...item.json,
    _raw_title_cleaned: cleaned,
    _category_path: [category, subcat, subsubcat].filter(Boolean).join(' > '),
    _description_preview: description
  }
};

let aiTitle = '';
try {
  aiTitle = (item.json.choices[0].message.content || '').trim().replace(/^"|"$/g, '').replace(/^'|'$/g, '').trim();
} catch (e) { aiTitle = ''; }
if (aiTitle.length > 80) {
  aiTitle = aiTitle.substring(0, 80);
  const lastSpace = aiTitle.lastIndexOf(' ');
  if (lastSpace > 50) aiTitle = aiTitle.substring(0, lastSpace);
}
const fallback = item.json._raw_title_cleaned || item.json['Title'] || '';
const finalTitle = (aiTitle.length > 5) ? aiTitle : fallback.substring(0, 80);
return {
  json: {
    ...item.json,
    _ebay_title: finalTitle,
    _title_length: finalTitle.length,
    _title_source: aiTitle.length > 5 ? 'ai' : 'fallback'
  }
};

const cfg = item.json._config;
const costRaw = item.json['Cost per item'] || '0';
let cost = parseFloat(String(costRaw).replace(/[^0-9.]/g, '')) || 0;
if (cost === 0) return { json: { ...item.json, _ebay_price: null, _price_error: 'Cost is 0' } };
let rebateApplied = 0;
if (cfg.applyActiveRebate) {
  const rebatePct = parseFloat(item.json['Rebate %'] || '0') || 0;
  const rebateStart = item.json['Rebate Start Date'] || '';
  const rebateEnd = item.json['Rebate End Date'] || '';
  const now = new Date();
  let active = rebatePct > 0;
  if (rebateStart && rebateEnd) {
    active = rebatePct > 0 && now >= new Date(rebateStart) && now <= new Date(rebateEnd);
  }
  if (active) {
    rebateApplied = cost * (rebatePct / 100);
    cost -= rebateApplied;
  }
}
const metroColumns = ['Delivery(ACT)', 'Delivery(NSW_M)', 'Delivery(QLD_M)', 'Delivery(SA_M)', 'Delivery(VIC_M)', 'Delivery(WA_M)'];
let shippingCost = cfg.shippingFallback;
if (!cfg.useFixedShipping) {
  const metros = metroColumns.map(c => parseFloat(String(item.json[c] || '0').replace(/[^0-9.]/g, ''))).filter(v => v > 0);
  if (metros.length > 0) shippingCost = Math.max(...metros);
} else { shippingCost = cfg.estimatedShippingCost; }
let price;
if (cfg.pricingMode === 'percentage') price = cost * cfg.markupMultiplier;
else if (cfg.pricingMode === 'flat') price = cost + cfg.flatFee;
else price = (cost * cfg.markupMultiplier) + cfg.flatFee;
if (cfg.includeFreeShipping) price += shippingCost;
if (cfg.applyEbayFeeBuffer) price = price / (1 - cfg.ebayFeeRate);
if (price < cfg.minimumListingPrice) price = cfg.minimumListingPrice;
if (cfg.charmPrice && price > 1) {
  price = Math.ceil(price) - 0.01;
  if (price < cfg.minimumListingPrice) price = cfg.minimumListingPrice;
}
const finalPrice = parseFloat(price.toFixed(2));
const ebayFee = parseFloat((finalPrice * cfg.ebayFeeRate).toFixed(2));
const profit = parseFloat((finalPrice - cost - shippingCost - ebayFee).toFixed(2));
const marginPct = parseFloat(((profit / finalPrice) * 100).toFixed(1));
return {
  json: {
    ...item.json,
    _cost_after_rebate: parseFloat(cost.toFixed(2)),
    _rebate_applied: parseFloat(rebateApplied.toFixed(2)),
    _shipping_baked: parseFloat(shippingCost.toFixed(2)),
    _ebay_fee_est: ebayFee,
    _ebay_price: finalPrice.toFixed(2),
    _profit_estimate: profit,
    _margin_pct: marginPct
  }
};

const cfg = item.json._config;
const imageList = [item.json['Image 1'], item.json['Image 2'], item.json['Image 3'], item.json['Image 4'], item.json['Image 5'], item.json['Image 6']]
  .map(u => (u || '').trim()).filter(u => u.length > 0 && u.startsWith('http'));
if (imageList.length === 0) return { json: { ...item.json, _ebay_images: '', _image_error: 'No images' } };
const cloudName = cfg.cloudinaryCloudName;
const wId = cfg.watermarkPublicId;
const gravity = cfg.watermarkGravity || 'north_west';
const widthScale = (cfg.watermarkWidthPct / 100).toFixed(2);
const xOffset = cfg.watermarkXOffset || 0;
const yOffset = cfg.watermarkYOffset || 0;
const opacity = cfg.watermarkOpacity || 95;
const watermarkLayer = `l_${wId},w_${widthScale},c_scale,g_${gravity},x_${xOffset},y_${yOffset},o_${opacity},fl_relative`;
// Option A: Only Image 1 gets Cloudinary watermark badge; secondary gallery images stay direct CDN URLs
const allImages = imageList.map((url, idx) => idx === 0 ? `https://res.cloudinary.com/${cloudName}/image/fetch/${watermarkLayer}/${url}` : url);
const picURLs = allImages.join('|');
return {
  json: {
    ...item.json,
    _ebay_images: picURLs,
    _primary_watermarked: allImages[0],
    _image_count: allImages.length
  }
};

const title = item.json._ebay_title || item.json['Title'] || '';
const rawDesc = item.json['Description'] || '';
const sku = item.json['SKU'] || '';
const category = item.json['Category'] || '';
const subcat = item.json['Subcategory'] || '';
const subsubcat = item.json['Sub_subcategory'] || '';
const warranty = item.json['Warranty'] || 'default';
const warrantyDisplay = (warranty === 'default' || !warranty || warranty.trim() === '') ? '12 Months' : warranty;
const cleanText = rawDesc.replace(/<img[^>]+>/gi, '').replace(/<h[1-6][^>]*>([^<]+)<\/h[1-6]>/gi, '$1. ').replace(/<li[^>]*>([^<]+)<\/li>/gi, '• $1\n').replace(/<strong>([^<]+)<\/strong>/gi, '$1').replace(/<[^>]+>/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&nbsp;/g, ' ').replace(/\s{2,}/g, ' ').trim();
const bullets = cleanText.split(/[\n•]/).map(s => s.trim()).filter(s => s.length > 15 && !s.toLowerCase().includes('return') && !s.toLowerCase().includes('refund')).slice(0, 7);
const bulletHTML = bullets.length > 0 ? bullets.map(b => `<li>${b.charAt(0).toUpperCase() + b.slice(1).replace(/\.?$/, '.')}</li>`).join('\n') : `<li>${cleanText.substring(0, 200)}</li>`;
const row = (label, value) => value && value !== 'default' ? `<tr><td style="padding:9px;font-weight:600;background:#f4f6f9;border-bottom:1px solid #dde3ec;width:180px;">${label}</td><td style="padding:9px;border-bottom:1px solid #dde3ec;">${value}</td></tr>` : '';
const categoryDisplay = [category, subcat, subsubcat].filter(s => s && s !== 'default').join(' › ');
const html = `<div style="max-width:820px;margin:0 auto;font-family:Arial,sans-serif;"><h1 style="font-size:20px;">${title}</h1><div style="background:#f5f8ff;padding:14px;"><h3>Features</h3><ul>${bulletHTML}</ul></div><table style="width:100%;border-collapse:collapse;">${row('SKU', sku)}${row('Category', categoryDisplay)}${row('Warranty', warrantyDisplay)}</table></div>`;
return { json: { ...item.json, _ebay_description_html: html } };

const CATEGORY_MAP = {
  'pickleball': '184357',
  'grooming': '177794',
  'clipper': '177794',
  'pet cleaning': '177794',
  'massage gun': '36449',
  'massager': '36449',
  'massage': '36449',
  'yoga mat': '158929',
  'yoga': '158929',
  'pilates': '158929',
  'laptop stand': '175685',
  'chopper': '20638',
  'kitchen': '20638',
  'fan': '43509',
  'headlamp': '106988',
  'kegel': '15280',
  'thigh': '15280',
  'radio': '96954',
  'cat carrier': '177789',
  'cat shelter': '177789',
  'christmas': '170090',
  'pillow': '20563',
  'wallet': '2996',
  'cat toy': '20741',
  'sewing': '20160',
  'table lamp': '20702',
  'bottle lamp': '20702',
  'shower': '181379',
  'hiking pole': '84886',
  'trekking': '84886',
  'mouse': '23160',
  'chest rig': '177880',
  'water bag': '181381',
  'ankle brace': '36449',
  'battle rope': '179803',
  'flosser': '106095',
  'oral care': '106095',
  'watch': '178893',
  'wristband': '178893',
  'scrubber': '20636',
  'lunch bag': '54316',
  'hair dryer': '101419',
  'lock picking': '183831',
  'gravity pick': '183831',
  'tools': '183831',
  'backpack': '169291',
  'hobo bag': '169291',
  'handbag': '169291',
  'default': '11700'
};
const cat = item.json['Category'] || '';
const subcat = item.json['Subcategory'] || '';
const subsubcat = item.json['Sub_subcategory'] || '';
const title = item.json._ebay_title || item.json['Title'] || '';
const searchText = `${subsubcat} ${subcat} ${cat} ${title}`.toLowerCase();
let categoryId = CATEGORY_MAP['default'];
for (const [k, v] of Object.entries(CATEGORY_MAP)) {
  if (k !== 'default' && searchText.includes(k)) { categoryId = v; break; }
}
const sku = item.json['SKU'] || '';
const rawQty = parseInt(item.json['QOH'] || '0', 10);
const listQty = Math.min(rawQty > 0 ? rawQty : 1, 3);

// Item specifics extraction
const desc = (item.json['Description'] || '').toLowerCase();
let material = 'High Quality Material';
const matMatches = [{ k: 'carbon fiber', v: 'Carbon Fiber' }, { k: 'fiberglass', v: 'Fiberglass' }, { k: 'stainless steel', v: 'Stainless Steel' }, { k: 'aluminum alloy', v: 'Aluminum Alloy' }, { k: 'pu leather', v: 'PU Leather' }, { k: 'memory foam', v: 'Memory Foam' }, { k: 'oxford', v: 'Oxford Fabric' }, { k: 'canvas', v: 'Canvas' }, { k: 'corduroy', v: 'Corduroy' }, { k: 'abs', v: 'ABS Plastic' }, { k: 'silicone', v: 'Silicone' }, { k: 'tpe', v: 'TPE' }, { k: 'pvc', v: 'Heavy Duty PVC' }];
for (const m of matMatches) { if (`${title} ${desc}`.toLowerCase().includes(m.k)) { material = m.v; break; } }
let colour = 'Multicoloured';
const colours = ['Black', 'White', 'Grey', 'Gray', 'Blue', 'Pink', 'Purple', 'Green', 'Silver', 'Gold', 'Yellow', 'Khaki', 'Beige', 'Red', 'Orange'];
for (const c of colours) { if (new RegExp(`\\b${c}\\b`, 'i').test(title)) { colour = c === 'Gray' ? 'Grey' : c; break; } }
let power = 'Manual / Non-Electric';
if (desc.includes('solar')) power = 'Solar Powered';
else if (desc.includes('rechargeable')) power = 'USB Rechargeable Battery';
else if (desc.includes('usb')) power = 'USB Powered';

let department = 'Unisex Adults';
if (searchText.includes('women') || searchText.includes('lady') || searchText.includes('hobo bag') || searchText.includes('handbag')) department = 'Women';
else if (searchText.includes('men') || searchText.includes('wallet')) department = 'Men';

let style = 'Modern';
if (searchText.includes('hobo')) style = 'Hobo Bag';
else if (searchText.includes('tote')) style = 'Tote';
else if (searchText.includes('shoulder')) style = 'Shoulder Bag';
else if (searchText.includes('backpack')) style = 'Backpack';
else if (searchText.includes('chest rig')) style = 'Tactical Bag';

const ebayRow = {
  '*Action': 'Add',
  '*Title': item.json._ebay_title,
  '*Category': categoryId,
  'CustomLabel': `DSZ-${sku}`,
  '*ConditionID': '1000',
  '*StartPrice': item.json._ebay_price,
  '*Quantity': listQty,
  '*Format': 'FixedPrice',
  '*Duration': 'GTC',
  'ShippingType': 'Free',
  'ShippingService-1:Option': 'AU_StandardDelivery',
  'ShippingService-1:Cost': '0.00',
  'DispatchTimeMax': '1',
  'Country': 'AU',
  '*Location': 'Australia',
  'PicURL': item.json._ebay_images,
  'C:Brand': 'Unbranded',
  'C:Type': subsubcat || subcat || 'Accessories',
  'C:Material': material,
  'C:Colour': colour,
  'C:Department': department,
  'C:Style': style,
  'C:Power Source': power,
  'C:Features': 'Portable, Lightweight, Durable',
  'C:MPN': `DSZ-${sku}`,
  'Description': item.json._ebay_description_html,
  '_dsz_sku': sku,
  '_profit_estimate': item.json._profit_estimate,
  '_margin_pct': item.json._margin_pct + '%'
};
return { json: ebayRow };
